return {
    ["skilldisc(*id)，随后化身残影，快速造成六次*d点伤害，期间buffdisc(*id)。*f秒后使律令爆发spellfielddisc(*id)。"] = "skilldisc(*id), после чего обращается в остаточную тень и быстро наносит шесть ударов по *d ед. урона, активируя на это время buffdisc(*id). Спустя *f сек. провоцирует взрыв Закона: spellfielddisc(*id).",
    ["不败旌旗"] = "Непобедимое знамя.",
    ["五次*d点伤害"] = "Пять случаев повреждения *d.",
    ["以灰雾至高位格影响目标—100%基础概率沉默*d秒。（影响同时自身获得灰雾加持效果）"] = false,
    ["以灰雾至高位格影响目标。（影响同时自身获得灰雾加持效果）"] = false,
    ["伦纳德吟诵安魂诗篇，使周围6米内目标获得70%重伤效果，持续4秒，自身获得持续<Highlight>6</>秒半径<Highlight>6</>米的宁静光环，光环可使敌人buffdisc(*id)。"] = "Леонард декламирует Успокоительную поэму, накладывая на цели в радиусе 6 м эффект 70% тяжёлого ранения на 4 сек., а сам получает ауру безмятежности радиусом <Highlight>6</> м на <Highlight>6</> сек., накладывающую на врагов buffdisc(*id).",
    ["伦纳德吟诵安魂诗篇，使敌方重伤并且自身获得光环，该光环可降低周围敌方目标移动速度。"] = "Леонард декламирует «Поэму Успокоения», нанося врагам тяжкие раны и окружая себя аурой, снижающей скорость передвижения ближайших врагов.",
    ["佛尔思召唤一道闪电，电击目标敌方造成*d伤害，若目标为怪物，则造成的伤害提升75%。"] = "Форс призывает молнию, поражая вражескую цель электрическим разрядом на *d ед. урона; если цель — монстр, наносимый урон увеличивается на 75%.",
    ["佛尔思召唤一道闪电，电击目标敌方造成一定伤害，若目标为怪物，则造成的伤害提升75%。"] = "Форс призывает молнию, поражая вражескую цель электрическим разрядом и нанося ей урон. Если цель — монстр, урон увеличивается на 75%.",
    ["午夜诗篇"] = "Полуночная поэма",
    ["历史明灯"] = "Маяк истории",
    ["可在<HighLight>旗帜</>持续时间内增加<HighLight>旗帜</>持续时间5秒，同时冷却时间增加15秒。"] = "Пока действует <HighLight>Знамя</>, можно продлить действие <HighLight>Знамени</> на 5 сек., при этом время перезарядки увеличивается на 15 сек.",
    ["可在旗帜持续时间内增加旗帜持续时间，同时增加该技能冷却时间。"] = "Пока действует Знамя, продлевает время его действия, одновременно увеличивая время перезарядки навыка.",
    ["合奏诗篇"] = "Совместная поэма",
    ["向前方连续发射两发空气炮，造成两次*d点伤害，只命中一个目标时单次伤害增加至*d点。"] = "Выпускает вперёд два воздушных выстрела подряд, наносящих дважды по *d ед. урона; если поражена только одна цель, разовый урон возрастает до *d ед.",
    ["圣光庇护"] = "Покровительство Священного Света",
    ["奥黛丽为目标友方回复*d点生命值，并为目标友方附加<FaintYellow>审视</>效果，持续<HighLight>4</>秒，记录<HighLight>4</>秒内受到的伤害，在效果结束时，根据效果期间所受的伤害的<HighLight>40%</>回复生命值。"] = "Одри восстанавливает *d ед. здоровья выбранному союзнику и накладывает на него эффект <FaintYellow>Пристальный взгляд</> на <HighLight>4</> сек., фиксируя полученный за <HighLight>4</> сек. урон. По окончании действия эффекта цель восстанавливает здоровье в размере <HighLight>40%</> от полученного за это время урона.",
    ["奥黛丽为目标友方附加<FaintYellow>审视</>效果，一定时间内记录伤害，时间结束后按照一定比例回复生命值。"] = "Одри накладывает эффект <FaintYellow>Пристальный взгляд</> на выбранного союзника, фиксируя полученный урон в течение определённого времени, по истечении которого восстанавливает здоровье в процентном соотношении.",
    ["奥黛丽为目标友方附加<FaintYellow>审视</>效果，持续4秒，记录<HighLight>4</>秒内受到的伤害，在效果结束时，根据效果期间所受的伤害的<HighLight>40%</>回复生命值。"] = "Одри накладывает эффект <FaintYellow>Пристальный взгляд</> на выбранного союзника на 4 сек., фиксируя полученный за <HighLight>4</> сек. урон. По окончании действия эффекта цель восстанавливает здоровье в размере <HighLight>40%</> от полученного за это время урона.",
    ["奥黛丽抛出3块苏茜最爱的贝克兰德宠物饼干可以恢复友方生命值，碰触饼干也可以恢复友方生命值。"] = "Одри бросает 3 любимых бэкландских печенья для питомцев Суси, способных восстановить здоровье союзникам. Прикосновение к печенью также восстанавливает здоровье союзникам.",
    ["奥黛丽抛出3块苏茜珍藏的贝克兰德宠物饼干并回复周围生命值百分比最低的1个友方*d点生命值，碰触饼干可以回复周围生命值百分比最低的3个友方*d点生命值，若不触碰饼干，则饼干消失时可以回复周围生命值百分比最低的3个友方*d点生命值，饼干最多持续<HighLight>6</>秒。"] = "Одри бросает 3 припрятанных бэкландских печенья для питомцев Суси, восстанавливая *d ед. здоровья находящемуся поблизости союзнику с наименьшим процентом здоровья. Прикосновение к печенью восстанавливает *d ед. здоровья 3 находящимся поблизости союзникам с наименьшим процентом здоровья. Если к печенью не прикоснуться, оно восстановит *d ед. здоровья 3 находящимся поблизости союзникам с наименьшим процентом здоровья в момент своего исчезновения. Печенье существует до <HighLight>6</> сек.",
    ["奥黛丽治疗目标友方，并为目标友方附加<FaintYellow>审视</>效果，一定时间内记录伤害，时间结束后按照一定比例回复生命值。"] = "Одри исцеляет выбранного союзника и накладывает на него эффект <FaintYellow>Пристальный взгляд</>, фиксируя полученный урон в течение определённого времени, по истечении которого восстанавливает здоровье в процентном соотношении.",
    ["对路径上的敌方目标造成*d伤害"] = "Наносит *d ед. урона вражеским целям на пути следования.",
    ["展开圣光领域，解除自身控制效果并且获得霸体、buffdisc(*id)，一段时间或再次释放后，skilldisc(*id)"] = "Разворачивает область Священного Света, снимает с себя эффекты контроля и получает Суперброню и buffdisc(*id). Спустя некоторое время или при повторном применении — skilldisc(*id).",
    ["展开圣光领域，解除自身控制效果并且获得霸体、减伤和护盾。一段时间或再次释放后，迸发能量攻击并且击退自身周围的敌人。"] = "Разворачивает область Священного Света, снимает с себя эффекты контроля и получает Суперброню, Снижение урона и щит. Спустя некоторое время или при повторном применении высвобождает всплеск энергии, атакуя и подбрасывая окружающих врагов.",
    ["帝国旗帜"] = "Имперское знамя",
    ["引导童话魔法，使目标深陷王国幻境中无法自拔，持续受到伤害并处于僵直状态。"] = "Направляет сказочную магию, погружая цель в непреодолимую иллюзию сказочного королевства: враг непрерывно получает урон и находится в состоянии оцепенения.",
    ["引导童话魔法，使目标深陷王国幻境中无法自拔，持续处于僵直状态。在目标位置制造童话王国的幻境，对范围内的敌人造成skilldisc(*id)。引导期间自身获得霸体，可通过闪避提前打断。完整引导王国幻境后会引爆幻境skilldisc(*id)。"] = "Направляет сказочную магию, погружая цель глубоко в иллюзию сказочного королевства и удерживая её в оцепенении. Создаёт в точке нахождения цели иллюзию сказочного королевства, наносящую skilldisc(*id) врагам в области действия. Во время поддержания навыка дарует Суперброню; применение можно прервать уклонением. Полное поддержание взрывает иллюзию, вызывая skilldisc(*id).",
    ["弗兰克在目标敌方位置召唤一个特制蘑菇，蘑菇引爆造成spellfielddisc(*id)范围伤害。"] = "Фрэнк выращивает особый гриб в точке врага, подрыв которого наносит spellfielddisc(*id) ед. урона по площади.",
    ["弗兰克在目标敌方位置召唤一个特制蘑菇，蘑菇引爆造成一定范围伤害。"] = "Франк призывает особый гриб в точке нахождения врага; взрыв гриба наносит урон по определённой области.",
    ["弗莱对敌方玩家造成*d点伤害，对敌方怪物造成*d点伤害，并为目标敌方附加<FaintYellow>死灵印记</>，持续10秒，buffdisc(*id)"] = "Фрай наносит *d ед. урона вражеским игрокам и *d ед. урона вражеским монстрам, накладывая на цель <FaintYellow>Некротическую метку</> на 10 сек., buffdisc(*id).",
    ["弗莱对目标敌方造成伤害，并为目标敌方附加<FaintYellow>死灵印记</>，使其在受到施法者的攻击时额外承受施法者攻击力一定比例的伤害。"] = "Фрай наносит урон вражеской цели и накладывает на неё <FaintYellow>Некротическую метку</>, из-за чего при атаках заклинателя она получает дополнительный урон в размере доли от силы атаки заклинателя.",
    ["律令裁决"] = "Суд Закона",
