    ["班森进行讨价还价，随机掷出1-5枚硬币，根据硬币数量决定折扣力度，根据折扣力度获得增益。"] = "Бенсон торгуется, случайно бросая 1-5 монет. Размер скидки зависит от количества монет, и он получает усиление в зависимости от величины скидки.",
    ["班森进行讨价还价，随机掷出<FaintYellow>1-5</>枚硬币，根据硬币数量决定折扣力度，根据折扣力度获得增益。"] = "Бенсон торгуется, случайно бросая <FaintYellow>1-5</> монет. Размер скидки зависит от количества монет, и он получает усиление в зависимости от величины скидки.",
    ["班森进行讨价还价，随机掷出<HighLight>1-5</>枚，根据硬币数量决定折扣力度，根据折扣力度令自身获得增益，持续<HighLight>9</>秒。\n<HighLight>1</>枚九折：buffdisc(*id)\n<HighLight>2</>枚八折：buffdisc(*id)\n<HighLight>3</>枚七折：buffdisc(*id)\n<HighLight>4</>枚六折：buffdisc(*id)\n<HighLight>5</>枚五折：buffdisc(*id)"] = "Бенсон торгуется, случайным образом выбрасывая <HighLight>1-5</> монет, и определяет интенсивность скидки в зависимости от количества монет. Он получит выигрыш в зависимости от интенсивности скидки, которая длится <HighLight>9</> секунд. \n<HighLight>1</> Скидка 10 %: buffdisc(*id)\n<HighLight>2</> Скидка 20 %: buffdisc(*id)\n<HighLight>3</> Скидка 30 % на каждый предмет: buffdisc(*id)\n<HighLight>4</> Скидка 40 % на каждый предмет: buffdisc(*id)\n<HighLight>5</> Скидка 50%: buffdisc(*id)",
    ["电场"] = "Электрическое поле",
    ["瞬移至目标身前，对周围的敌人附加律令，使其buffdisc(*id)*f秒"] = "Телепортируется к цели и накладывает Приказ на окружающих врагов, подвергая их buffdisc(*id) на *f сек.",
    ["瞬移至目标身前，眩晕周围的敌人并且施展多段斩击，期间自身获得减伤。"] = "Мгновенно перемещается перед целью, оглушает окружающих врагов и проводит серию рассекающих ударов, получая снижение урона на время действия.",
    ["神奇蘑菇"] = "Чудодейственный гриб",
    ["空气炮"] = "Воздушная пушка",
    ["窥探命运的秘密，一段时间内提升自身和自身周围友方的伤害。"] = "Приоткрывает тайны судьбы, на некоторое время увеличивая урон себе и окружающим соратникам.",
    ["窥探命运的秘密，使自身和自身周围友方的buffdisc(*id)。"] = "Приоткрывает тайны судьбы, наделяя себя и окружающих соратников buffdisc(*id).",
    ["窥秘预言"] = "Пророчество Тайноведения",
    ["罗塞尔在目标位置树立<HighLight>帝国旗帜</>，<HighLight>旗帜</>具有血量可以被攻击，<HighLight>帝国旗帜</>存在时间内颁布<HighLight>律令</>：敌方每次闪避消耗的体力值翻倍，移速降低，己方多个<HighLight>旗帜</>效果不叠加，该技能体力消耗相应的效果不受其他体力消耗速率效果的影响。"] = "Розель водружает в указанной точке <HighLight>знамя Империи</>. <HighLight>Знамя</> обладает запасом здоровья и может быть атаковано. Пока существует <HighLight>знамя Империи</>, действует <HighLight>указ</>: расход выносливости противников при каждом уклонении удваивается, скорость передвижения снижается. Эффекты нескольких союзных <HighLight>знамен</> не суммируются; эффекты расхода выносливости от этого навыка не зависят от прочих модификаторов скорости расхода выносливости.",
    ["罗塞尔在目标位置树立<HighLight>帝国旗帜</>，<HighLight>旗帜</>继承250%生命值，<HighLight>帝国旗帜</>存在时间内，<HighLight>旗帜</>周围12米半径内颁布<HighLight>律令</>：敌方每次闪避消耗的体力值翻倍，移动速度降低15%，<HighLight>旗帜</>持续12秒，己方多个<HighLight>旗帜</>效果不叠加，该技能体力消耗相应的效果不受其他体力消耗速率效果的影响。"] = "Розель водружает <HighLight>Имперское знамя</> в указанной точке. <HighLight>Знамя</> наследует 250% здоровья. Пока существует <HighLight>Имперское знамя</>, в радиусе 12 метров вокруг <HighLight>Знамени</> провозглашается <HighLight>Приказ</>: расход выносливости врагов на каждое уклонение удваивается, а скорость бега снижается на 15%. <HighLight>Знамя</> существует 12 секунд. Эффекты от нескольких союзных <HighLight>Знамён</> не суммируются. Эффект расхода выносливости от этого навыка не зависит от других модификаторов расхода выносливости.",
    ["自身获得灰雾加持，提高增伤。"] = "Обретает благословение Серого Тумана, повышая наносимый урон.",
    ["若自身和合奏效果的队友对同一个目标造成伤害，则额外造成伤害。"] = "Если вы и товарищи по команде с помощью ансамблевых эффектов нанесете урон одной и той же цели, будет нанесен дополнительный урон.",
    ["若自身和合奏效果的队友对同一个目标造成伤害，则额外造成目标已损失血量<Highlight>10%</>的伤害，2秒只能触发1次。"] = "Если вы и соратник под эффектом Ансамбля наносите урон одной и той же цели, наносится дополнительный урон в размере <Highlight>10%</> от потерянного здоровья цели; срабатывает не чаще одного раза в 2 секунды.",
    ["获得灰雾加持，buffdisc(*id)，持续*d秒。"] = "Обретает благословение Серого Тумана, buffdisc(*id) на *d сек.",
    ["血肉阴影"] = "Тень плоти",
    ["装备技能后：每<FaintYellow>5</>秒获得一层债务，上限<FaintYellow>4</>层。\n使用技能：老尼尔消耗所有债务对目标造成伤害，消耗的债务越多造成的伤害越高。"] = "После экипировки навыка: каждые <FaintYellow>5</> сек. накапливает 1 уровень Долга, максимум до <FaintYellow>4</> уровней.\nПри использовании: старик Нил поглощает весь Долг и наносит урон цели. Чем больше потрачено уровней Долга, тем выше урон.",
    ["装备技能后：每<FaintYellow>5</>秒获得一层债务，上限<FaintYellow>4</>层。\n使用技能：老尼尔消耗所有债务对目标造成伤害，消耗的债务越多造成的伤害越高，对怪物伤害提高100%。"] = "После установки навыка: каждые <FaintYellow>5</> сек. накапливается 1 стак Долга, максимум до <FaintYellow>4</> стаков.\nПрименение навыка: Старина Нил поглощает весь Долг и наносит урон цели. Чем больше Долга поглощено, тем выше урон; урон по монстрам увеличивается на 100%.",
    ["装备技能后：每<HighLight>5</>秒获得一层债务，上限<HighLight>4</>层。\n使用技能：老尼尔消耗所有债务对目标造成<HighLight>3</>次伤害，消耗的债务越多造成的伤害越高，第1次skilldisc(*id)，第2次skilldisc(*id)，第3次skilldisc(*id)。"] = "После установки навыка: каждые <HighLight>5</> сек. даёт 1 уровень Долга (максимум <HighLight>4</> ур.).\nПрименение: Старик Нил расходует все уровни Долга, нанося цели урон <HighLight>3</> раза. Чем больше израсходовано Долга, тем выше урон: 1-й удар — skilldisc(*id), 2-й удар — skilldisc(*id), 3-й удар — skilldisc(*id).",
    ["装备技能后：每<HighLight>5</>秒获得一层债务，上限<HighLight>4</>层。\n使用技能：老尼尔消耗所有债务对目标造成<HighLight>3</>次伤害，消耗的债务越多造成的伤害越高，第1次skilldisc(*id)，第2次skilldisc(*id)，第3次skilldisc(*id)，目标个数最多为6个，对怪物伤害提高100%。"] = "После оснащения навыками: получайте слой долга каждые <HighLight>5</> секунд, максимум <HighLight>4</> слоев. \n Использование навыков: Старый Нил поглощает все долги, чтобы нанести цели <HighLight>3</> раз урона. Чем больше долгов потребляется, тем выше причиненный ущерб. При расходе 1 долга: skilldisc(*id); при расходе 2 долгов: skilldisc(*id); при расходе 3 долгов: skilldisc(*id). Максимальное количество целей — 6, а урон по монстрам увеличен на 100%.",
    ["讨价还价"] = "Торг",
    ["转运仪式"] = "Ритуал повышения удачи.",
    ["还债"] = "Уплата долга.",
    ["迸发能量攻击对四周敌人造成*d点伤害并且将其击退。"] = "Взрыв энергии наносит *d ед. урона окружающим врагам и отбрасывает их назад.",
    ["通灵仪式"] = "Спиритический ритуал",
    ["通过仪式引导，在自身周围摆下转运仪式，需要逆走四步（完成顺序4→3→2→1，仪式需20秒内完成），仪式完毕后，转运仪式获得二段技能—灰雾加持：点击二段技能后方可触发仪式效果，自身获得灰雾加持。若未在指定时间内完成仪式，则返还部分技能冷却时间。"] = "Руководствуясь ритуалом, разверните вокруг себя Ритуал повышения удачи. Требуется пройти четыре шага против часовой стрелки (порядок шагов: 4→3→2→1, ритуал необходимо завершить в течение 20 секунд). После завершения ритуала открывается навык второй стадии — «Благословение Серого Тумана»: нажмите на него, чтобы активировать эффект и получить Благословение Серого Тумана. Если ритуал не завершён за отведённое время, возвращается часть времени перезарядки навыка.",
    ["通过仪式引导，在自身周围摆下转运仪式，需要逆走四步（完成顺序4→3→2→1，仪式需20秒内完成），仪式完毕后，转运仪式获得二段技能—灰雾加持：点击二段技能后方可触发仪式效果，自身获得灰雾加持，持续10秒，获得20%增伤。若未在指定时间内完成仪式，则返还10秒冷却时间。"] = "Руководствуясь ритуалом, разверните вокруг себя Ритуал повышения удачи. Требуется пройти четыре шага против часовой стрелки (порядок шагов: 4→3→2→1, ритуал необходимо завершить в течение 20 секунд). После завершения ритуала открывается навык второй стадии — «Благословение Серого Тумана»: нажмите на него, чтобы активировать эффект и получить Благословение Серого Тумана на 10 сек., повышающее урон на 20%. Если ритуал не завершён за отведённое время, возвращается 10 секунд времени перезарядки.",
    ["造成*d点伤害，中心区域伤害增加为*d点"] = "Наносит *d ед. урона; урон в центральной зоне увеличивается до *d ед.",
    ["造成*d范围伤害"] = "Наносит *d ед. урона по площади.",
    ["邓恩将梦魇的力量注入地面，凝聚成梦魇向目标敌方冲击，命中目标敌方后造成bulletdisc(*id)点伤害，并且给目标留下梦魇标记，1.5秒时间结束后造成*d点额外伤害。"] = "Данн направляет силу Кошмара в землю, сгущая её в фантом ночного кошмара, который устремляется к вражеской цели; при попадании наносит bulletdisc(*id) ед. урона и оставляет на цели метку Кошмара, которая по прошествии 1,5 сек. наносит *d ед. дополнительного урона.",
    ["邓恩将梦魇的力量注入地面，凝聚成梦魇对目标敌方造成一定伤害，并且给目标留下梦魇标记，标记结束后造成一定伤害。"] = "Данн направляет силу Кошмара в землю, сгущая её в кошмарный фантом, который наносит урон вражеской цели и оставляет на ней метку Кошмара; по истечении метки цель получает дополнительный урон.",
    ["阿兹克召唤白骨信使的死亡之爪对锁定目标进行拍击，对锁定目标及其周围最多3个其他目标造成*d点伤害。死亡之爪同时会为锁定目标附加<HighLight>死亡侵蚀</>效果，持续4秒，每秒造成一定伤害。"] = false,
    ["阿兹克召唤白骨信使的死亡之爪对锁定目标进行拍击，对锁定目标及其周围最多3个其他目标造成伤害。死亡之爪同时会为锁定目标附加<HighLight>死亡侵蚀</>效果。"] = false,
    ["阿兹克对目标造成少量伤害，若目标身上具有死亡侵蚀，则造成大量伤害。"] = "Азик наносит цели небольшой урон; если цель поражена эрозией смерти, наносится огромный урон.",
    ["驭浪"] = "Покорение волн",
    ["驾驭海浪，可以通过方向键调整冲锋方向，期间获得最高4秒霸体、5秒加速效果。冲锋结束或手动释放二段时，造成*d点伤害。\n装备技能获得被动：大世界中水上滑板和水中游泳速度增加5%。"] = "Оседлайте морские волны: клавишами направления можно менять вектор рывка; на это время даётся до 4 сек. Суперброни и на 5 сек. ускорение. По окончании рывка или при ручной активации второй фазы наносит *d ед. урона.\nПассивный эффект от экипировки навыка: скорость передвижения на водной доске и плавания в открытом мире увеличивается на 5%.",
    ["驾驭海浪，获得霸体和加速效果，可以通过方向键调整冲锋方向。冲锋结束或手动释放二段时，对周身敌人发动攻击，装备技能可增加自身在水上滑板和水中游泳的速度。"] = "Оседлайте морскую волну, получая суперброню и ускорение; направление рывка можно менять клавишами движения. В конце рывка или при повторной активации атакует врагов вокруг. Экипированный навык увеличивает скорость скольжения по воде и плавания.",
}
